from d1_pricing import bulk_discount, line_total, parse_sku

def test_discount():
    assert bulk_discount(100) == 0.15
    assert bulk_discount(99) == 0.05
    assert bulk_discount(20) == 0.05
    assert bulk_discount(19) == 0.0

def test_line_total():
    assert line_total(2.5, 19) == round(2.5 * 19, 2)
    assert line_total(3.0, 100) == round(3.0 * 100 * (1 - 0.15), 2)

def test_parse_sku():
    assert parse_sku("AB/0042/Z") == {"category": "AB", "number": 42, "variant": "Z"}
    assert parse_sku("WXYZ/9999/A")["number"] == 9999
    for bad in ["ab/0042/Z", "AB/42/Z", "AB/0042", "ABCDE/0042/Z", "AB/0042/ZZ"]:
        try:
            parse_sku(bad)
        except ValueError:
            continue
        raise AssertionError("accepted " + bad)

